def listar_fila(usuario_id, apenas_meus=False):
    conexao = banco.conectar()
    sql = "SELECT id, titulo, prioridade, status, criado_em, responsavel_id FROM ticket WHERE status != 'fechado'"
    if apenas_meus:
        sql += f" AND responsavel_id = {usuario_id}"
    tickets = conexao.consultar(sql)

    ordem = {"urgente": 0, "alta": 1, "media": 2, "baixa": 3}
    tickets = sorted(tickets, key=lambda t: (ordem.get(t["prioridade"], 9), t["criado_em"]))

    saida = []
    for ticket in tickets:
        responsavel = conexao.consultar(f"SELECT nome FROM usuario WHERE id = {ticket['responsavel_id']}")
        saida.append({
            "id": ticket["id"],
            "titulo": ticket["titulo"],
            "prioridade": ticket["prioridade"],
            "responsavel": responsavel[0]["nome"] if responsavel else None,
            "aberto_ha_horas": (datetime.now() - ticket["criado_em"]).total_seconds() / 3600,
        })
    return saida

