async function carregar(filtros) {
  const resposta = await fetch('/api/tickets?' + new URLSearchParams(filtros))
  const tickets = await resposta.json()
  render(tickets)
}

function render(tickets) {
  tabela.innerHTML = tickets
    .map((t) => `<tr><td>${t.id}</td><td>${t.titulo}</td></tr>`)
    .join('')
}

